	CONSTRAINT "booking_status" CHECK (status IN ('confirmed','cancelled')),
	CONSTRAINT "booking_version" CHECK (version > 0),
	CONSTRAINT "booking_target" CHECK ((target_type='vehicle' AND target_vehicle_id IS NOT NULL AND target_model_id IS NULL AND target_brand_id IS NULL AND target_group_id IS NULL) OR (target_type='model' AND target_model_id IS NOT NULL AND target_vehicle_id IS NULL AND target_brand_id IS NULL AND target_group_id IS NULL) OR (target_type='brand' AND target_brand_id IS NOT NULL AND target_vehicle_id IS NULL AND target_model_id IS NULL AND target_group_id IS NULL) OR (target_type='equivalence_group' AND target_group_id IS NOT NULL AND target_vehicle_id IS NULL AND target_model_id IS NULL AND target_brand_id IS NULL))
);
